(30411, 'Philippians 4:1', 'Philippians', 4, 1, 'نو ای زما ګرانو خویندو او ورونو! زه ستاسو د لیدلو په ارمان یم. تاسو زما خوشحالي او زما ویاړ یئ. نو بیا ای ګرانو دوستانو، په څښتن کې همداسې ټینګ اوسئ. هڅونې او لارښوونې', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/philippians4_verse_1.mp3', '', 1761754199, 1761754199),
(30412, 'Philippians 4:2', 'Philippians', 4, 2, 'زه افودیه او سینتیخې ته زاري کوم چې په څښتن کې په یو فکر اوسئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/philippians4_verse_2.mp3', '', 1761754199, 1761754199),
(30413, 'Philippians 4:3', 'Philippians', 4, 3, 'هو، زما رښتینی ملګریه، ستا څخه غوښتنه کوم چې د دې دوه ښځو سره مرسته وکړې، ځکه چې هغوی د کلیمانتوس او زما د نورو همکارانو سره د زېري په خپرولو کې څنګ تر‌څنګ هلې ځلې کړي دي او نومونه یې د ژوندون په کتاب کې لیکل شوي دي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/philippians4_verse_3.mp3', '', 1761754199, 1761754199),
(30414, 'Philippians 4:4', 'Philippians', 4, 4, 'تل په څښتن کې خوشحالي کوئ او بیاهم وایم چې خوشحاله اوسئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/philippians4_verse_4.mp3', '', 1761754199, 1761754199),
(30415, 'Philippians 4:5', 'Philippians', 4, 5, 'پرېږده چې ستاسو نرم مزاجي او مهرباني ټولو خلکو ته ښکاره شي. څښتن به زر راشي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/philippians4_verse_5.mp3', '', 1761754199, 1761754199),
(30416, 'Philippians 4:6', 'Philippians', 4, 6, 'د هېڅ شي په هکله اندېښنه مه کوئ، بلکې تل د شکرګزارۍ په دعاګانو او زاریو سره خپلې غوښتنې د خدای حضور ته وړاندې کوئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/philippians4_verse_6.mp3', '', 1761754199, 1761754199),
(30417, 'Philippians 4:7', 'Philippians', 4, 7, 'نو بیا د خدای سوله او سلامتي چې د انسان د پوهې نه لوړه ده، ستاسو زړونه او خیالونه به د عیسی مسیح په وسیله خوندي وساتي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/philippians4_verse_7.mp3', '', 1761754199, 1761754199),
(30418, 'Philippians 4:8', 'Philippians', 4, 8, 'اخر دا چې ای خویندو او ورونو! هر هغه څه چې رښتیا، عزتمن، عادلانه، پاک، زړه وړونکي، ښکلي او هغه څه چې ډېر ښه او د ستاینې وړ دي، د هغو په هکله فکر کوئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/philippians4_verse_8.mp3', '', 1761754199, 1761754199),
(30419, 'Philippians 4:9', 'Philippians', 4, 9, 'هغه څه چې تاسو زما نه زده کړي او حاصل کړي دي یا مو زما نه اورېدلي او لیدلي دي، هغه سرته ورسوئ، نو بیا به خدای چې د سولې او سلامتۍ سرچینه ده، ستاسو سره مل وي. د خدای د مرستو او د فیلیپیانو د تحفو څخه مننه کول', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/philippians4_verse_9.mp3', '', 1761754199, 1761754199),
(30420, 'Philippians 4:10', 'Philippians', 4, 10, 'زه په څښتن کې ډېر خوشحاله یم چې له څه مودې وروسته یوځل بیا ستاسو پام زما خواته شو. زه پوهېږم چې تاسو په رښتیا زما سره علاقه درلودله، خو تاسو سره د هغو د ښکاره کولو موقعه پیدا نه شوه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/philippians4_verse_10.mp3', '', 1761754199, 1761754199),
(30421, 'Philippians 4:11', 'Philippians', 4, 11, 'زه دا خبرې د دې دپاره نه کوم چې محتاج یم، بلکې دا مې زده کړل چې زه په هرحال کې یم، راضي یم.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/philippians4_verse_11.mp3', '', 1761754199, 1761754199),
(30422, 'Philippians 4:12', 'Philippians', 4, 12, 'زه پوهېږم چې څرنګه په غریبۍ کې یا شتمنۍ کې ژوند وکړم. ما په هر ډول حالاتو کې ژوند کړی دی او د ژوند کولو راز مې زده کړی دی، که زه موړ وم یا وږی یا که محتاج وم یا هرڅه مې لرل.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/philippians4_verse_12.mp3', '', 1761754199, 1761754199),
(30423, 'Philippians 4:13', 'Philippians', 4, 13, 'زه د مسیح په وسیله چې ماته قوت راکوي کولای شم چې هر حالت تېر کړم.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/philippians4_verse_13.mp3', '', 1761754199, 1761754199),
(30424, 'Philippians 4:14', 'Philippians', 4, 14, 'په هر حال دا ستاسو مهرباني وه چې زما سره مو په سختیو کې مرسته وکړه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/philippians4_verse_14.mp3', '', 1761754199, 1761754199),
(30425, 'Philippians 4:15', 'Philippians', 4, 15, 'ای د فیلیپې د ښار ایماندارانو، تاسو ښه خبر یئ چې د زېري د رسولو په لومړیو ورځو کې کله چې زه د مقدونیې څخه روان شوم، نو هېڅ یوه کلیسا زما سره په ګټه او تاوان کې شریکه نه شوه، پرته له تاسو نه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/philippians4_verse_15.mp3', '', 1761754199, 1761754199),
(30426, 'Philippians 4:16', 'Philippians', 4, 16, 'حتی کله چې په تسالونیکیه کې وم څو ځلې مو زما د اړتیاوو د پوره کولو دپاره مرسته راولېږله.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/philippians4_verse_16.mp3', '', 1761754199, 1761754199),
(30427, 'Philippians 4:17', 'Philippians', 4, 17, 'زه دا خبره د دې دپاره نه کوم چې ستاسو نه صرف کومه مالي مرسته تر‌لاسه کړم، بلکې زه غواړم چې ستاسو د نېکو کارونو اجر دې ستاسو په حساب کې ورزیات شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/philippians4_verse_17.mp3', '', 1761754199, 1761754199),
(30428, 'Philippians 4:18', 'Philippians', 4, 18, 'خو اوس ستاسو هرڅه ماته راورسېدل او حتی زما د اړتیا نه زیات. تاسو چې د اپافرودیتوس په لاس کومې مالي مرستې رالېږلې وې په هغو باندې زما اړتیاوې په کامله توګه پوره شوې. دا هغه د خوشبویۍ نذرانه او قرباني ده چې خدای ته قبوله او د هغه خوښه ده.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/philippians4_verse_18.mp3', '', 1761754199, 1761754199),
(30429, 'Philippians 4:19', 'Philippians', 4, 19, 'زما خدای به ستاسو ټولې اړتیاوې د خپلې پرېمانه شتمنۍ له مخې د عیسی مسیح په وسیله پوره کړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/philippians4_verse_19.mp3', '', 1761754199, 1761754199),
(30430, 'Philippians 4:20', 'Philippians', 4, 20, 'خدای ته چې زمونږ اسماني پلار دی، تل ترتله جلال وي. امین. وروستني سلامونه', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/philippians4_verse_20.mp3', '', 1761754199, 1761754199),
(30431, 'Philippians 4:21', 'Philippians', 4, 21, 'د خدای ټولو خلکو ته چې د عیسی مسیح سره تړاو لري، سلامونه ووایئ. کوم ورونه چې زما سره دي، هغوی هم تاسو ته سلامونه وایي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/philippians4_verse_21.mp3', '', 1761754199, 1761754199),
(30432, 'Philippians 4:22', 'Philippians', 4, 22, 'د خدای ټول خلک چې دلته دي تاسو ته سلام وایي، په ځانګړې توګه هغوی چې د روم د امپراتور په ماڼۍ کې اوسیږي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/philippians4_verse_22.mp3', '', 1761754199, 1761754199),
(30433, 'Philippians 4:23', 'Philippians', 4, 23, 'په تاسو ټولو باندې دې د څښتن عیسی مسیح فضل وي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/philippians4_verse_23.mp3', '', 1761754199, 1761754199),
(30434, 'Revelation 7:1', 'Revelation', 7, 1, 'له دې نه وروسته مې څلور فرښتې ولیدلې چې د ځمکې په څلورو کنجونو کې ولاړې وې او د څلور واړو بادونو مخه یې نیولې وه، ترڅو په ځمکه، بحر او یا په کومه ونه باندې ونه لګیږي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation7_verse_1.mp3', '', 1761754199, 1761754199),
(30435, 'Revelation 7:2', 'Revelation', 7, 2, 'بیا ما بله فرښته ولیدله چې د لمرخاته خوا نه راپورته کېدله او د ژوندي خدای مهر ورسره ؤ او په لوړ اواز یې هغو څلورو فرښتو ته نارې ووهلې چې دا اختیار ورته ورکړل شوی ؤ چې ځمکې او بحر ته زیان ورسوي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation7_verse_2.mp3', '', 1761754199, 1761754199),
(30436, 'Revelation 7:3', 'Revelation', 7, 3, 'هغې فرښتې وویل: «ترڅو پورې چې مونږ د خدای د خدمتګارانو په تندیو باندې مهر نه وي لګولی، تر هغې پورې ځمکې، بحر یا ونو ته زیان ونه رسوئ.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation7_verse_3.mp3', '', 1761754199, 1761754199),
(30437, 'Revelation 7:4', 'Revelation', 7, 4, 'بیا مې واورېده چې د هغو کسانو شمېر چې په تندیو باندې یې مهر لګېدلی ؤ، ۱۴۴۰۰۰ تنه ؤ. هغوی د اسراییلو د ټولو قبیلو څخه وو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation7_verse_4.mp3', '', 1761754199, 1761754199),
(30438, 'Revelation 7:5', 'Revelation', 7, 5, 'دولس زره د یهودا د قبیلې څخه دولس زره د روبین د قبیلې څخه دولس زره د جاد د قبیلې څخه', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation7_verse_5.mp3', '', 1761754199, 1761754199),
(30439, 'Revelation 7:6', 'Revelation', 7, 6, 'دولس زره د اشیر د قبیلې څخه دولس زره د نفتالي د قبیلې څخه دولس زره د منسي د قبیلې څخه', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation7_verse_6.mp3', '', 1761754199, 1761754199),
(30440, 'Revelation 7:7', 'Revelation', 7, 7, 'دولس زره د شمعون د قبیلې څخه دولس زره د لاوي د قبیلې څخه دولس زره د ایساکار د قبیلې څخه', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation7_verse_7.mp3', '', 1761754199, 1761754199),
(30441, 'Revelation 7:8', 'Revelation', 7, 8, 'دولس زره د زبولون د قبیلې څخه دولس زره د یوسف د قبیلې څخه دولس زره د بنیامین د قبیلې څخه. د ټولو قومونو یوه لویه ګڼه‌ګوڼه', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation7_verse_8.mp3', '', 1761754199, 1761754199),
(30442, 'Revelation 7:9', 'Revelation', 7, 9, 'له دې وروسته مې وکتل او د خلکو یوه لویه ګڼه‌ګوڼه مې ولیدله چې هېچا نه شو کولای هغه وشمېري. د ټولو ملتونو، قبیلو، قومونو او ژبو نه خلک د تخت په مخکې او د وري په وړاندې ولاړ وو. هغوی سپینې چپنې اغوستې وې او د خرما د ونو څانګې یې په لاس کې وې،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation7_verse_9.mp3', '', 1761754199, 1761754199),
(30443, 'Revelation 7:10', 'Revelation', 7, 10, 'او په لوړ اواز یې نارې وهلې: «زمونږ خلاصون د خدای له خوا دی چې په تخت باندې ناست دی او د وري له خوا دی.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation7_verse_10.mp3', '', 1761754199, 1761754199),
(30444, 'Revelation 7:11', 'Revelation', 7, 11, 'ټولې فرښتې د تخت، د مشرانو او څلور اسماني موجوداتو ګردچاپېره ولاړې وې، او بیا د تخت په مخکې پړمخې پرېوتلې او د خدای عبادت یې وکړ', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation7_verse_11.mp3', '', 1761754199, 1761754199),
(30445, 'Revelation 7:12', 'Revelation', 7, 12, 'هغوی ویل: امین! ثنا او صفت او جلال حکمت او شکرګزاري عزت، قدرت او قوت دې وي تل ترتله زمونږ د خدای، امین!', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation7_verse_12.mp3', '', 1761754199, 1761754199),
(30446, 'Revelation 7:13', 'Revelation', 7, 13, 'بیا د مشرانو څخه یو تن زما څخه پوښتنه وکړه: «دا خلک چې سپینې چپنې یې اغوستې دي څوک دي او له کوم ځای نه راغلي دي؟»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation7_verse_13.mp3', '', 1761754199, 1761754199),
(30447, 'Revelation 7:14', 'Revelation', 7, 14, 'ما ځواب ورکړ: «ښاغلیه، ته پوهېږې.» بیا هغه راته وویل: «دا هغه کسان دي چې د سخت مصیبت څخه تېر شوي دي. هغوی خپلې چپنې د وري په وینو وینځلې او سپینې کړي دي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation7_verse_14.mp3', '', 1761754199, 1761754199),
(30448, 'Revelation 7:15', 'Revelation', 7, 15, 'له دې امله دي ولاړ هغوی د خدای د تخت په مخکې او شپه او ورځ کوي خدمت د هغه کور کې چې په تخت باندې ناست دی هغه څوک په خپل شتون کې به پناه ورکړي هغوی ته او کوي ساتنه به یې', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation7_verse_15.mp3', '', 1761754199, 1761754199),
(30449, 'Revelation 7:16', 'Revelation', 7, 16, 'نور به هېڅکله نه وږي کیږي هغوی او هم تږي کیږي به نه زیان به ونه رسوي دوی ته نه لمر او نه سوځوونکې ګرمي', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation7_verse_16.mp3', '', 1761754199, 1761754199),
(30450, 'Revelation 7:17', 'Revelation', 7, 17, 'ځکه هغه وری چې دی د تخت په منځ کې هغه به کړي د دوی شپونتوب او د ژوندون د اوبو چینو ته به بیایي هغوی او خدای به پاکې ټولې اوښکې کړي د هغوی له سترګو څخه»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation7_verse_17.mp3', '', 1761754199, 1761754199),
(30451, 'Ephesians 2:1', 'Ephesians', 2, 1, 'تاسو یو وخت د خپلې سرغړونې او ګناهونو له امله مړه وئ،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/ephesians2_verse_1.mp3', '', 1761754199, 1761754199),
(30452, 'Ephesians 2:2', 'Ephesians', 2, 2, 'او د دې دنیا په کږو لارو باندې روان وئ او د فضا د روحاني قدرتونو د واکمن یعنې د هماغه روح څخه مو پیروي کوله چې اوس په نافرمانو خلکو کې کار کوي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/ephesians2_verse_2.mp3', '', 1761754199, 1761754199),
(30453, 'Ephesians 2:3', 'Ephesians', 2, 3, 'یو وخت مونږ هم لکه د هغوی په شان د خپلو جسماني غوښتنو له مخې ژوند تېراوه او خپلې نفساني او فکري غوښتنې مو پوره کولې. مونږ هم لکه د نورو انسانانو په شان په طبیعي توګه د خدای د غضب لایق وو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/ephesians2_verse_3.mp3', '', 1761754199, 1761754199),
(30454, 'Ephesians 2:4', 'Ephesians', 2, 4, 'خو خدای چې په رحم غني دی زمونږ سره یې ډېره مینه وکړه،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/ephesians2_verse_4.mp3', '', 1761754199, 1761754199),
(30455, 'Ephesians 2:5', 'Ephesians', 2, 5, 'حتی کله چې مونږ د خپلو سرغړونو له امله مړه شوي وو، هغه مونږ د مسیح سره یوځای د مړو نه راپورته کړو، نو د هغه د فضل په وسیله تاسو خلاصون وموند.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/ephesians2_verse_5.mp3', '', 1761754199, 1761754199),
(30456, 'Ephesians 2:6', 'Ephesians', 2, 6, 'خدای مونږ د عیسی مسیح سره په یووالي کې هم په روحاني توګه د مړو نه راپورته کړو او مونږ یې د هغه سره په اسماني ځایونو کې کښېنولو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/ephesians2_verse_6.mp3', '', 1761754199, 1761754199),
(30457, 'Ephesians 2:7', 'Ephesians', 2, 7, 'هغه داسې وکړ، ترڅو په راتلونکو زمانو کې د خپل فضل لویه او بې‌حده شتمني د خپلې مهربانۍ له مخې په عیسی مسیح کې مونږ ته ښکاره کړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/ephesians2_verse_7.mp3', '', 1761754199, 1761754199),
(30458, 'Ephesians 2:8', 'Ephesians', 2, 8, 'ځکه چې تاسو د خدای د فضل په سبب او ایمان له لارې خلاصون موندلی دی او دا ستاسو خپل کار نه دی بلکې دا د خدای یو نعمت دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/ephesians2_verse_8.mp3', '', 1761754199, 1761754199),
(30459, 'Ephesians 2:9', 'Ephesians', 2, 9, 'خلاصون ستاسو د کار نتیجه نه ده، نو هېڅوک ویاړ نه شې کولای.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/ephesians2_verse_9.mp3', '', 1761754199, 1761754199),
(30460, 'Ephesians 2:10', 'Ephesians', 2, 10, 'ځکه چې مونږ د هغه په لاس جوړ شوي یو او په عیسی مسیح کې د نېکو کارونو دپاره پیدا شوي یو چې خدای د مخکې نه زمونږ دپاره تیار کړي وو، ترڅو سرته یې ورسوو. په مسیح کې یووالی', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/ephesians2_verse_10.mp3', '', 1761754199, 1761754199),
(30461, 'Ephesians 2:11', 'Ephesians', 2, 11, 'نو له دې امله یاد ساتئ چې یو وخت تاسو غیریهودیان د سنت شویو په نظر کې چې دا خپله یو جسماني عمل دی او د انسان په وسیله سرته رسیږي، ناسنت شوي ګڼل کېدلئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/ephesians2_verse_11.mp3', '', 1761754199, 1761754199),
(30462, 'Ephesians 2:12', 'Ephesians', 2, 12, 'یاد ساتئ چې تاسو په هغه زمانه کې د مسیح نه بېل وئ او د اسراییلو په قوم کې شامل نه وئ او تاسو د خدای د هغو لوظونو نه بې‌برخې وئ چې د هغې وعدې له مخي شوي وو چې خدای د خپلو خلکو سره کړې وه. تاسو په دې دنیا کې نا‌امیده او د خدای نه لرې ژوند کاوه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/ephesians2_verse_12.mp3', '', 1761754199, 1761754199),
(30463, 'Ephesians 2:13', 'Ephesians', 2, 13, 'خو اوس تاسو په عیسی مسیح کې چې یو وخت د خدای نه لېرې وئ د هغه د وینې په وسیله هغه ته نژدې شوي یئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/ephesians2_verse_13.mp3', '', 1761754199, 1761754199),
(30464, 'Ephesians 2:14', 'Ephesians', 2, 14, 'ځکه چې مسیح زمونږ سوله او سلامتي ده او هغه دوه ډلې سره یو کړلې او د خپل بدن په وسیله یې د دښمنۍ هغه دېوال وران کړ چې هغوی یې سره بېل کړي وو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/ephesians2_verse_14.mp3', '', 1761754199, 1761754199),
(30465, 'Ephesians 2:15', 'Ephesians', 2, 15, 'هغه شریعت د هغه د حکمونو او مقرراتو سره منسوخ کړ، ترڅو په خپل بدن کې د دې دوه ډلو نه یو نوی قوم جوړ کړي او سوله او سلامتي راولي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/ephesians2_verse_15.mp3', '', 1761754199, 1761754199),
(30466, 'Ephesians 2:16', 'Ephesians', 2, 16, 'مسیح په صلیب باندې د خپل مرګ په وسیله دواړه ډلې په یو بدن کې د خدای سره پخلا کړې، ترڅو د یهودیانو او غیریهودیانو دښمني له منځه یوسي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/ephesians2_verse_16.mp3', '', 1761754199, 1761754199),
(30467, 'Ephesians 2:17', 'Ephesians', 2, 17, 'هغه راغی ترڅو د سولې او سلامتۍ زېری تاسو ته چې د خدای نه لېرې وئ او هغوی ته چې خدای ته نژدې وو، اعلان کړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/ephesians2_verse_17.mp3', '', 1761754199, 1761754199),
(30468, 'Ephesians 2:18', 'Ephesians', 2, 18, 'ځکه چې مونږ دواړه د مسیح په وسیله په یو روح القدس کې پلار خدای خواته ورنژدې کېږو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/ephesians2_verse_18.mp3', '', 1761754199, 1761754199),
(30469, 'Ephesians 2:19', 'Ephesians', 2, 19, 'نو نور تاسو پردي او مسافر نه یئ بلکې د خدای د خلکو وطنداران او د خدای د کورنۍ غړي یئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/ephesians2_verse_19.mp3', '', 1761754199, 1761754199),
(30470, 'Ephesians 2:20', 'Ephesians', 2, 20, 'تاسو د رسولانو او پیغمبرانو په بنیاد جوړ شوي یئ چې عیسی مسیح په خپله د هغه بنیاد اصلي تیږه ده.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/ephesians2_verse_20.mp3', '', 1761754199, 1761754199),
(30471, 'Ephesians 2:21', 'Ephesians', 2, 21, 'په هغه کې د ودانۍ ټولې برخې سره یوځای کیږي او په څښتن کې ترې یو سپېڅلی کور جوړیږي او وده کوي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/ephesians2_verse_21.mp3', '', 1761754199, 1761754199),
(30472, 'Ephesians 2:22', 'Ephesians', 2, 22, 'نو ستاسو نه هم په هغه کې د نورو سره یو کور جوړیږي چې خدای د خپل روح په وسیله په هغه کې اوسیږي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/ephesians2_verse_22.mp3', '', 1761754199, 1761754199),
(30473, 'Mark 14:1', 'Mark', 14, 1, 'د فسحې او د فطیرې ډوډۍ اختر ته دوه ورځې پاتې وې. مشران کاهنان او د شریعت عالمان په دې لټه کې وو چې څنګه عیسی په پټه راونیسي او ویې وژني.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark14_verse_1.mp3', '', 1761754199, 1761754199),
(30474, 'Mark 14:2', 'Mark', 14, 2, 'هغوی وویل: «خو دا کار باید د اختر په ورځو کې ونه شي، هسې نه چې خلک شور او غوغا جوړه کړي.» یوه ښخه د عیسی په سر باندې عطر اچوي (متي ۲۶‏:‌۶‌‏-‌۱۳ او یوحنا ۱۲‏:‌۱‌‏-‌۸)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark14_verse_2.mp3', '', 1761754199, 1761754199),
(30475, 'Mark 14:3', 'Mark', 14, 3, 'عیسی په بیت‌عنیا کې د شمعون په کور کې چې مخکې یې د جذام ناروغي لرله، دسترخوان ته ناست ؤ. یوه ښځه راغله او د مرمرو بوتل ورسره ؤ چې د سنبل د قیمتي عطرو څخه ډک ؤ. هغې د بوتل سر مات کړ او د عیسی په سر باندې یې واچول.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark14_verse_3.mp3', '', 1761754199, 1761754199),
(30476, 'Mark 14:4', 'Mark', 14, 4, 'په هغه ځای کې د حاضرو خلکو څخه ځینې یې په قهر شول او یو بل ته یې سره وویل: «دا عطر ولې داسې بېځایه ضایع شول؟', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark14_verse_4.mp3', '', 1761754199, 1761754199),
(30477, 'Mark 14:5', 'Mark', 14, 5, 'کېدای شول چې دا عطر د سپینو زرو د درې سوه سکو څخه په زیاته بیه خرڅ شوي وای او پیسې یې غریبانو ته ورکړل شوې وای.» نو هغوی هغه ښځه ورټله.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark14_verse_5.mp3', '', 1761754199, 1761754199),
(30478, 'Mark 14:6', 'Mark', 14, 6, 'خو عیسی وویل: «د هغې سره کار مه لرئ! هغه ولې تنګوئ؟ هغې زما سره ښه کار کړی دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark14_verse_6.mp3', '', 1761754199, 1761754199),
(30479, 'Mark 14:7', 'Mark', 14, 7, 'غریبان به تل ستاسو سره وي او هر وخت چې وغواړئ د هغوی سره مرسته کولای شئ، خو زه به تل ستاسو سره نه یم.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark14_verse_7.mp3', '', 1761754199, 1761754199),
(30480, 'Mark 14:8', 'Mark', 14, 8, 'دې ښځې چې څه کولای شول ویې کړل. هغې زما په بدن باندې عطر واچول چې د ښخولو څخه مې مخکې تیار کړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark14_verse_8.mp3', '', 1761754199, 1761754199),
(30481, 'Mark 14:9', 'Mark', 14, 9, 'په یقین سره زه تاسو ته دا وایم چې د نړۍ په هرځای کې چې زېری ورکول کیږي، نو دې ښځې چې څه کړي دي خلک به هغه یادوي.» د عیسی سره د خیانت کولو دسیسه (متي ۲۶‏:‌۱۴‌‏-‌۱۶ او لوقا ۲۲‏:‌۳‌‏-‌۶)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark14_verse_9.mp3', '', 1761754199, 1761754199),
(30482, 'Mark 14:10', 'Mark', 14, 10, 'بیا یهودا اسخریوتي چې د هغو دولسو شاګردانو څخه ؤ، مشرانو کاهنانو ته ورغی چې عیسی هغوی ته په لاس ورکړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark14_verse_10.mp3', '', 1761754199, 1761754199),
(30483, 'Mark 14:11', 'Mark', 14, 11, 'کله چې هغوی دا واورېدل، نو خوشحاله شول او د هغه سره یې د پیسو وعده وکړه. نو یهودا د یوې موقعې په لټه کې ؤ ترڅو عیسی هغوی ته په لاس ورکړي. د فسحې د اختر ډوډۍ (متي ۲۶‏:‌۱۷‌‏-‌۲۵ او لوقا ۲۲‏:‌۷‌‏-‌۱۴،‌۲۱‌‏-‌۲۳ او یوحنا ۱۳‏:‌۲۱‌‏-‌۳۰)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark14_verse_11.mp3', '', 1761754199, 1761754199),
(30484, 'Mark 14:12', 'Mark', 14, 12, 'د فطیرې ډوډۍ د اختر په لومړۍ ورځ یعنې په هغه ورځ چې هغوی د فسحې وری قرباني کاوه، د عیسی شاګردانو هغه ته وویل: «ته چېرته غواړې چې د فسحې ډوډۍ درته تیاره کړو؟»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark14_verse_12.mp3', '', 1761754199, 1761754199),
(30485, 'Mark 14:13', 'Mark', 14, 13, 'نو عیسی خپل دوه شاګردان ولېږل او ورته ویې ویل: «ښار ته لاړ شئ، یو سړی به ووینئ چې د اوبو منګی وړي. په هغه پسې لاړ شئ', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark14_verse_13.mp3', '', 1761754199, 1761754199),
(30486, 'Mark 14:14', 'Mark', 14, 14, 'او کوم کور ته چې هغه ورننوت، تاسو هم ورشئ او د کور خاوند ته ووایئ: ‹استاذ وایي د مېلمنو هغه کوټه چېرته ده چې زه او زما شاګردان به په کې د فسحې ډوډۍ وخورو؟›', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark14_verse_14.mp3', '', 1761754199, 1761754199),
(30487, 'Mark 14:15', 'Mark', 14, 15, 'هغه به تاسو ته پاس په بالاخانه کې یوه لویه فرش شوې کوټه دروښایي. هلته زمونږ دپاره ډوډۍ تیاره کړئ.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark14_verse_15.mp3', '', 1761754199, 1761754199),
(30488, 'Mark 14:16', 'Mark', 14, 16, 'بیا شاګردان روان شول او ښار ته لاړل نو هغوی ټول شیان هماغه شان ولیدل لکه څنګه چې عیسی ورته ویلي وو، نو هغوی د فسحې ډوډۍ تیاره کړه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark14_verse_16.mp3', '', 1761754199, 1761754199),
(30489, 'Mark 14:17', 'Mark', 14, 17, 'کله چې ماښام شو، نو عیسی د دولسو شاګردانو سره راغی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark14_verse_17.mp3', '', 1761754199, 1761754199),
(30490, 'Mark 14:18', 'Mark', 14, 18, 'کله چې هغوی دسترخوان ته کښېناستل او ډوډۍ یې خوړله، عیسی وویل: «په یقین سره زه تاسو ته دا وایم چې په تاسو کې به یو تن چې زما سره ډوډۍ خوري، زما سره خیانت وکړي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark14_verse_18.mp3', '', 1761754199, 1761754199),
(30491, 'Mark 14:19', 'Mark', 14, 19, 'په دې خبره شاګردان ډېر غمجن شول او هر یو د عیسی څخه پوښتنه وکړه: «ایا هغه زه یم؟»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark14_verse_19.mp3', '', 1761754199, 1761754199),
(30492, 'Mark 14:20', 'Mark', 14, 20, 'عیسی هغوی ته ځواب ورکړ: «هغه ستاسو دولسو تنو څخه دی چې زما سره په یوه کاسه کې لاس ښکته کوي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark14_verse_20.mp3', '', 1761754199, 1761754199),
(30493, 'Mark 14:21', 'Mark', 14, 21, 'لکه څنګه چې د خدای په کلام کې لیکل شوي دي، د انسان زوی باید مړ شي، خو افسوس د هغه چا په حال چې د انسان د زوی سره خیانت کوي! د هغه سړي دپاره به ښه وه چې هېڅ پیدا شوی نه وای.» د څښتن غوره ماښامی (متي ۲۶‏:‌۲۶‌‏-‌۳۰ او لوقا ۲۲‏:‌۱۴‌‏-‌۲۰ او لومړی قرنتیان ۱۱‏:‌۲۳‌‏-‌۲۵)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark14_verse_21.mp3', '', 1761754199, 1761754199),
(30494, 'Mark 14:22', 'Mark', 14, 22, 'د ډوډۍ خوړلو په وخت کې عیسی یوه ډوډۍ راواخیستله، شکر یې پرې وویست، هغه یې ماته کړه، شاګردانو ته یې ورکړه او ویې ویل: «دا واخلئ، دا زما بدن دی.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark14_verse_22.mp3', '', 1761754199, 1761754199),
(30495, 'Mark 14:23', 'Mark', 14, 23, 'بیا هغه پیاله راواخیستله او د خدای شکر یې وویست او هغوی ته یې ورکړه او د هغې نه ټولو وڅښل.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark14_verse_23.mp3', '', 1761754199, 1761754199),
(30496, 'Mark 14:24', 'Mark', 14, 24, 'عیسی وویل: «دا زما وینه ده چې د خدای او انسان ترمنځ لوظ ټینګوي چې د ډېرو خلکو دپاره توییږي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark14_verse_24.mp3', '', 1761754199, 1761754199),
(30497, 'Mark 14:25', 'Mark', 14, 25, 'په یقین سره زه تاسو ته دا وایم چې بیا به تر هغې ورځې پورې دا د انګورو شربت ونه څښم ترڅو د خدای په پاچاهۍ کې یې بیا ونه څښم.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark14_verse_25.mp3', '', 1761754199, 1761754199),
(30498, 'Mark 14:26', 'Mark', 14, 26, 'بیا د یوې روحاني سندرې د ویلو څخه وروسته د زیتون غره ته لاړل. د پطروس د انکار په هکله پېشګویي (متي ۲۶‏:‌۳۱‌‏-‌۳۵ او لوقا ۲۲‏:‌۳۱‌‏-‌۳۴ او یوحنا ۱۳‏:‌۳۶‌‏-‌۳۸)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark14_verse_26.mp3', '', 1761754199, 1761754199),
(30499, 'Mark 14:27', 'Mark', 14, 27, 'عیسی خپلو شاګردانو ته وویل: «تاسو ټول به وتښتئ او ما به پرېږدئ، ځکه چې د خدای په کلام کې لیکل شوي دي: زه به شپون ووهم او پسونه به خواره واره شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark14_verse_27.mp3', '', 1761754199, 1761754199),
(30500, 'Mark 14:28', 'Mark', 14, 28, 'خو کله چې بیا راژوندی شم، نو ستاسو نه مخکې به جلیل ته لاړ شم.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark14_verse_28.mp3', '', 1761754199, 1761754199),
(30501, 'Mark 14:29', 'Mark', 14, 29, 'پطروس عیسی ته وویل: «حتی که ټول تا پرېږدي، خو زه به دې هېڅکله هم پرېنږدم.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark14_verse_29.mp3', '', 1761754199, 1761754199),
(30502, 'Mark 14:30', 'Mark', 14, 30, 'عیسی پطروس ته وویل: «په یقین سره زه تاته دا وایم چې همدا نن شپه به مخکې له دې چې چرګ دوه ځلې اذان وکړي، ته به درې ځلې ووایې چې ما نه پېژنې.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark14_verse_30.mp3', '', 1761754199, 1761754199),
(30503, 'Mark 14:31', 'Mark', 14, 31, 'خو پطروس په ټینګه وویل: «که زه تا سره مړ هم شم، خو هېڅکله به ونه وایم چې تا نه پېژنم.» او نورو ټولو شاګردانو هم همداسې وویل. عیسی په جتسیماني کې دعا کوي (متي ۲۶‏:‌۳۶‌‏-‌۴۶ او لوقا ۲۲‏:‌۳۹‌‏-‌۴۶)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark14_verse_31.mp3', '', 1761754199, 1761754199),
(30504, 'Mark 14:32', 'Mark', 14, 32, 'هغوی د جتسیماني په نوم یو ځای ته ورسېدل، نو عیسی خپلو شاګردانو ته وویل: «تاسو دلته کښېنئ او زه دعا کوم.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark14_verse_32.mp3', '', 1761754199, 1761754199),
(30505, 'Mark 14:33', 'Mark', 14, 33, 'بیا هغه پطروس، یعقوب او یوحنا د ځان سره بوتلل. عیسی ډېر غمجن شو او زړه یې تنګ شو،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark14_verse_33.mp3', '', 1761754199, 1761754199),
(30506, 'Mark 14:34', 'Mark', 14, 34, 'او هغوی ته یې وویل: «زما زړه له غمه چوي او مرګ ته نژدې یم. دلته پاتې شئ او بېداره اوسئ.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark14_verse_34.mp3', '', 1761754199, 1761754199),
(30507, 'Mark 14:35', 'Mark', 14, 35, 'عیسی لږ لېرې لاړ او په ځمکه پرېوت او دعا یې وکړه چې که چېرې کېدای شي، نو دا د کړاو ساعت دې زما څخه تېر شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark14_verse_35.mp3', '', 1761754199, 1761754199),
(30508, 'Mark 14:36', 'Mark', 14, 36, 'هغه وویل: «ابا، یعنې ای پلاره! ستا دپاره هرڅه ممکن دي. دا پیاله زما څخه لېرې کړه، خو زما رضا نه بلکې لکه څنګه چې ستا رضا وي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark14_verse_36.mp3', '', 1761754199, 1761754199),
(30509, 'Mark 14:37', 'Mark', 14, 37, 'بیا عیسی بېرته شاګردانو ته راغی او ویې لیدل چې هغوی ویده دي. نو پطروس ته یې وویل: «ای شمعونه، ویده یې؟ ایا یو ساعت هم ویښ نه شوې پاتې کېدلی؟', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark14_verse_37.mp3', '', 1761754199, 1761754199),
(30510, 'Mark 14:38', 'Mark', 14, 38, 'بېداره اوسئ او دعا وکړئ چې د وسوسو سره مخامخ نه شئ، زړه غواړي خو بدن کمزوری دی.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark14_verse_38.mp3', '', 1761754199, 1761754199);